CREATE COLUMN TABLE "TEST_AP"."CTNS" ("AbsId" INTEGER CS_INT NOT NULL , "ObjectId" NVARCHAR(30) NOT NULL , "EnableAsyN" NVARCHAR(1) DEFAULT 'N', "EnableTn" NVARCHAR(1) DEFAULT 'Y', "EnablePTn" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
